-- Additive catalogue experience schema. No existing records are deleted.
BEGIN;
CREATE TABLE IF NOT EXISTS public.experience_preferences(user_id TEXT PRIMARY KEY REFERENCES public.users(id) ON DELETE CASCADE,settings_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS public.account_collections(user_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,kind TEXT NOT NULL,listing_id TEXT NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,kind,listing_id));
CREATE TABLE IF NOT EXISTS public.conversation_preferences(user_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,conversation_id TEXT NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,muted INTEGER NOT NULL DEFAULT 0,archived INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,conversation_id));
CREATE TABLE IF NOT EXISTS public.seller_quick_replies(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,title TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public.listing_insights(listing_id TEXT NOT NULL REFERENCES public.listings(id),day TEXT NOT NULL,kind TEXT NOT NULL,total INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(listing_id,day,kind));
CREATE TABLE IF NOT EXISTS public.listing_view_keys(listing_id TEXT NOT NULL REFERENCES public.listings(id),day TEXT NOT NULL,visitor_key TEXT NOT NULL,PRIMARY KEY(listing_id,day,visitor_key));
CREATE TABLE IF NOT EXISTS public.seller_stock_alerts(listing_id TEXT PRIMARY KEY REFERENCES public.listings(id) ON DELETE CASCADE,threshold INTEGER NOT NULL DEFAULT 2,alerted INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.seller_code_inventory(id TEXT PRIMARY KEY,listing_id TEXT NOT NULL REFERENCES public.listings(id),seller_id TEXT NOT NULL REFERENCES public.users(id),cipher TEXT NOT NULL,fingerprint TEXT NOT NULL,order_item_id TEXT REFERENCES public.order_items(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,allocated_at TEXT,UNIQUE(listing_id,fingerprint));
CREATE TABLE IF NOT EXISTS public.listing_imports(id TEXT PRIMARY KEY,seller_id TEXT NOT NULL REFERENCES public.users(id),rows_json TEXT NOT NULL,errors_json TEXT NOT NULL,expires_at TEXT NOT NULL,committed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public.notification_outbox(notification_id TEXT PRIMARY KEY REFERENCES public.notifications(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES public.users(id),status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS public.price_watches(user_id TEXT NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,listing_id TEXT NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE,target_minor BIGINT NOT NULL,last_triggered_minor BIGINT,PRIMARY KEY(user_id,listing_id));
CREATE TABLE IF NOT EXISTS public.message_retry_keys(conversation_id TEXT NOT NULL REFERENCES public.conversations(id) ON DELETE CASCADE,sender_id TEXT NOT NULL REFERENCES public.users(id),request_key TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES public.messages(id),PRIMARY KEY(conversation_id,sender_id,request_key));
CREATE INDEX IF NOT EXISTS idx_inventory_ready ON public.seller_code_inventory(listing_id,order_item_id);
CREATE INDEX IF NOT EXISTS idx_outbox_pending ON public.notification_outbox(status,created_at);
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS min_quantity INTEGER NOT NULL DEFAULT 1;
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS unit_label TEXT NOT NULL DEFAULT 'item';
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS automatic_delivery INTEGER NOT NULL DEFAULT 0;
ALTER TABLE public.listings ADD COLUMN IF NOT EXISTS corrections_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE public.experience_preferences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.experience_preferences FROM PUBLIC, anon, authenticated;
ALTER TABLE public.account_collections ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.account_collections FROM PUBLIC, anon, authenticated;
ALTER TABLE public.conversation_preferences ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.conversation_preferences FROM PUBLIC, anon, authenticated;
ALTER TABLE public.seller_quick_replies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seller_quick_replies FROM PUBLIC, anon, authenticated;
ALTER TABLE public.listing_insights ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.listing_insights FROM PUBLIC, anon, authenticated;
ALTER TABLE public.listing_view_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.listing_view_keys FROM PUBLIC, anon, authenticated;
ALTER TABLE public.seller_stock_alerts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seller_stock_alerts FROM PUBLIC, anon, authenticated;
ALTER TABLE public.seller_code_inventory ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.seller_code_inventory FROM PUBLIC, anon, authenticated;
ALTER TABLE public.listing_imports ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.listing_imports FROM PUBLIC, anon, authenticated;
ALTER TABLE public.notification_outbox ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.notification_outbox FROM PUBLIC, anon, authenticated;
ALTER TABLE public.price_watches ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.price_watches FROM PUBLIC, anon, authenticated;
ALTER TABLE public.message_retry_keys ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.message_retry_keys FROM PUBLIC, anon, authenticated;
COMMIT;
